import Foundation

/// The RP2040 boot ROM, revision B1, built from https://github.com/raspberrypi/pico-bootrom (BSD-3-Clause licence,
/// Copyright (c) 2020 Raspberry Pi (Trading) Ltd.), as rp2040js ships it: 16 KB, little-endian
enum RPBootrom {
    static let b1: [UInt32] = {
        let data = Data(base64Encoded: "")!
        return data.withUnsafeBytes { bytes in (0..<data.count / 4).map { bytes.loadUnaligned(fromByteOffset: $0 * 4, as: UInt32.self).littleEndian } }
    }()
}
